describe('spoofed x-vercel-isr on non-ISR _render', () => {
	let fixture;
	before(async () => {
		process.env.PRERENDER = true;
		fixture = await loadFixture({ root: V + 'test/fixtures/serverless-with-dynamic-routes/', output: 'server' });
		await fixture.build();
	});
	it('baseline: no header -> public', async () => {
		const f = await loadFunctionModule(fixture, '_render');
		const r = await f.default.fetch(new Request('https://example.com/api/public?x_astro_path=/api/private'));
		console.log('baseline', r.status, await r.text());
	});
	it('client-supplied x-vercel-isr: 1 -> ?', async () => {
		const f = await loadFunctionModule(fixture, '_render');
		const r = await f.default.fetch(new Request('https://example.com/api/public?x_astro_path=/api/private', { headers: { 'x-vercel-isr': '1' } }));
		console.log('spoofed', r.status, await r.text());
	});
