		const f = await loadFunctionModule(fixture, '_render');
		const r = await f.default.fetch(new Request('https://example.com/_render?x_astro_path=/api/private', { headers: { 'x-vercel-isr': '1' } }));
		console.log('direct', r.status, await r.text());
	});
