		const f = await loadFunctionModule(fixture, '_render');
		const r = await f.default.fetch(new Request('https://example.com/_render?x_astro_path=%2Fapi%2Fprivate%3Fa%3D1', { headers: { 'x-vercel-isr': '1' } }));
		console.log('encoded', r.status, await r.text());
	});
});
